def plain(x):
    if hasattr(x,'items'): return {str(k):plain(v) for k,v in x.items()}
    if isinstance(x,(tuple,list)): return [plain(v) for v in x]
    if isinstance(x,complex): return [x.real,x.imag]
    return x
def root(x): return sha256(json.dumps(plain(x),sort_keys=True,separators=(',',':'),default=str).encode()).hexdigest()
def write(name,x):
    x=plain(x)
    if isinstance(x,dict) and 'root' not in x: x['root']=root(x)
    (DOC/name).write_text(json.dumps(x,indent=2,sort_keys=True)+'\n')
